// The interface
public interface IProductRepository
{
    IEnumerable<Product> GetAll();
}

// The controller depends only on the interface
public class ProductsController : Controller
{
    private readonly IProductRepository _repo;

    public ProductsController(IProductRepository repo)
    {
        _repo = repo; // container provides the instance
    }

    public IActionResult Index()
    {
        return View(_repo.GetAll());
    }
}

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddTransient<IProductRepository, ProductRepository>();
builder.Services.AddControllersWithViews();

var app = builder.Build();
// ... middleware pipeline
app.Run();

public class ProductSum
{
    private readonly IProductRepository _repo;
    public ProductSum(IProductRepository repo) => _repo = repo;
    public decimal Total => _repo.GetAll().Sum(p => p.Price);
}

// Registration in Program.cs — single-type overload
builder.Services.AddTransient<ProductSum>();

var env = builder.Environment;

builder.Services.AddTransient<IProductRepository>(provider =>
{
    return env.IsDevelopment()
        ? new InMemoryProductRepository()
        : new SqlProductRepository(provider
            .GetRequiredService<IConfiguration>());
});

public class ProductsController : Controller
{
    private readonly IProductRepository _repo;

    public ProductsController(IProductRepository repo) => _repo = repo;

    // ProductSummary is resolved only when this action is called
    public IActionResult Summary([FromServices] ProductSummary summary)
    {
        ViewBag.TotalValue = summary.TotalValue;
        return View(_repo.GetAll());
    }
}
